// 🔴 修复：去掉所有异步/await/ESM兼容，纯CommonJS同步导入，完全没有语法问题
const { parentPort } = require('worker_threads');
const crypto = require('crypto');

// 独立SHA256实现
function sha256Buffer(msg) {
  return crypto.createHash('sha256').update(msg).digest();
}

// 监听任务
parentPort.on('message', (task) => {
  try {
    const { salt, challengeMap, startNonce, endNonce } = task;
    const localMap = new Map(Object.entries(challengeMap));
    let nonce = startNonce;

    while (nonce < endNonce && localMap.size > 0) {
      const hash = sha256Buffer(nonce + salt);
      const key = hash.toString('base64');
      
      if (localMap.has(key)) {
        const { index } = localMap.get(key);
        parentPort.postMessage({ 
          type: 'match', 
          data: { index, nonce }
        });
        localMap.delete(key);
      }
      nonce++;
    }

    parentPort.postMessage({ 
      type: 'done', 
      computedCount: nonce - startNonce 
    });
  } catch (e) {
    parentPort.postMessage({ type: 'error', msg: e.message });
  }
});
